			let drew = false;
			for (const n of ['panel-left', 'sidebar-left', 'sidebar',
				'folder-tree', 'files', 'file-text', 'file']) {
				btn.textContent = '';
				try { if (setIcon) setIcon(btn, n); } catch (_) {}
				if (btn.childElementCount > 0) { drew = true; break; }
			}
			if (!drew) btn.setText('☰');
